import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.CWgsre3x.js";const p=JSON.parse('{"title":"Create a phone-only booking","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/phone-only-booking.md","filePath":"tutorials/phone-only-booking.md"}'),i={name:"tutorials/phone-only-booking.md"};function r(s,e,l,c,h,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="create-a-phone-only-booking" tabindex="-1">Create a phone-only booking <a class="header-anchor" href="#create-a-phone-only-booking" aria-label="Permalink to &quot;Create a phone-only booking&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Source-reviewed training draft · TransferBook+ v0.7.9. Verify installed release, permissions and configuration. Use authorized synthetic training data; no live activation is implied.</p></div><h2 id="training-scenario" tabindex="-1">Training scenario <a class="header-anchor" href="#training-scenario" aria-label="Permalink to &quot;Training scenario&quot;">​</a></h2><p>A passenger requests a one-way transfer by telephone and has no email address. Use an authorized training workspace and a synthetic passenger record. A configured route, active market and suitable vehicle class are required.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Open the new reservation form. Select the active operating hub and one-way service.</li><li>Choose two distinct catalogue locations. Set pickup date, time, passenger and luggage counts.</li><li>Select a class with sufficient capacity. Enter the synthetic guest name and telephone. Leave <strong>Email (Optional)</strong> blank.</li><li>Review the tariff and wait for the server-verified quote in authenticated mode. If a manual quote is required, follow the manual quotation procedure instead.</li><li>Submit once, then locate the resulting reference in Reservations. Verify the route, time, phone and blank email.</li></ol><h2 id="check-your-result" tabindex="-1">Check your result <a class="header-anchor" href="#check-your-result" aria-label="Permalink to &quot;Check your result&quot;">​</a></h2><p>A missing email alone must not prevent booking. If the outcome is uncertain, search before creating another request. Never invent an email.</p><p>See <a href="/plus/create-reservation.html">Create a reservation</a> and <a href="/plus/passenger-information.html">Passenger information</a>.</p>',9)])])}const m=a(i,[["render",r]]);export{p as __pageData,m as default};
